    Bug 2044266 - Fix memory leak in NntpChannel. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D304016

diff --git a/mailnews/news/src/NntpChannel.sys.mjs b/mailnews/news/src/NntpChannel.sys.mjs
index c10ce427a3a..82a7c3331f8 100644
--- a/mailnews/news/src/NntpChannel.sys.mjs
+++ b/mailnews/news/src/NntpChannel.sys.mjs
@@ -260,6 +260,7 @@ export class NntpChannel extends MailChannel {
         try {
           this.loadGroup?.removeRequest(this, null, Cr.NS_OK);
         } catch (e) {}
+        this._listener = null;
         this._pending = false;
       },
       onDataAvailable: (request, stream, offset, count) => {
@@ -337,6 +338,7 @@ export class NntpChannel extends MailChannel {
         this._newsFolder?.msgDatabase.commit(
           Ci.nsMsgDBCommitType.kSessionCommit
         );
+        this._listener = null;
         this._pending = false;
       };
     });
@@ -371,6 +373,7 @@ export class NntpChannel extends MailChannel {
       client.onDone = status => {
         newsFolder.removeMessages([...allKeys]);
         this._listener.onStopRequest(this, status);
+        this._listener = null;
         this._pending = false;
       };
     });
